/** Routix 2: route-first, sober six-workspace interface. */
public class RoutixActivity extends AppCompatActivity implements LocationListener {
    private static final int LOCATION_PERMISSION=42, IMPORT_GPX=1337;
    private static final int BG=Color.rgb(17,17,27), SURFACE=Color.rgb(30,30,46), SURFACE2=Color.rgb(49,50,68);
    private static final int TEXT=Color.rgb(205,214,244), MUTED=Color.rgb(166,173,200), GREEN=Color.rgb(166,227,161), PEACH=Color.rgb(250,179,135), RED=Color.rgb(243,139,168), MAUVE=Color.rgb(203,166,247);

    private SharedPreferences prefs; private RouteStore store; private WorkHoursStore hoursStore; private LocationManager lm; private Location lastLocation;
    private FrameLayout root; private MapView map; private View topBar,dock,recordSheet; private LinearLayout contentHost; private CompactSpeedometer headerSpeed; private MyLocationNewOverlay me;
    private Polyline remainingLine; private RouteArrowsOverlay routeArrows; private int systemTop,systemBottom; private String selectedTab="map"; private int accent=MAUVE;
    private final List<RouteStore.Point> recordingPoints=new ArrayList<>(); private final List<RouteStore.Event> recordingEvents=new ArrayList<>();
    private boolean recording,paused,guiding; private long recordingStarted,pauseStarted,pausedTotal,lastDraftAt; private double recordedDistance;
    private TextView recordMain,recordStatus,recordDistance,recordPoints,recordEvents,reverseButton,twoSidesButton,pauseButton,guideTitle,guideDistance,guideProgress;
    private GuidanceEngine guidance; private RouteStore.Summary guidingRoute;

    @Override protected void onCreate(Bundle state){
        super.onCreate(state); WindowCompat.setDecorFitsSystemWindows(getWindow(),false); getWindow().setStatusBarColor(Color.TRANSPARENT); getWindow().setNavigationBarColor(BG);
        prefs=getSharedPreferences("routix",MODE_PRIVATE); accent=prefs.getInt("accent_color",MAUVE); store=new RouteStore(this,prefs); hoursStore=new WorkHoursStore(prefs); lm=(LocationManager)getSystemService(LOCATION_SERVICE);
        Configuration.getInstance().setUserAgentValue(getPackageName()+"/2.0 Routix"); Configuration.getInstance().setOsmdroidBasePath(new File(getCacheDir(),"osmdroid")); Configuration.getInstance().setOsmdroidTileCache(new File(getCacheDir(),"osmdroid/tiles"));
        root=new FrameLayout(this); root.setBackgroundColor(BG); buildMap(); topBar=buildTopBar(); contentHost=new LinearLayout(this); contentHost.setOrientation(LinearLayout.VERTICAL); dock=buildDock(); root.addView(topBar); root.addView(contentHost); root.addView(dock); setContentView(root);
        ViewCompat.setOnApplyWindowInsetsListener(root,(v,in)->{androidx.core.graphics.Insets b=in.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());systemTop=b.top;systemBottom=b.bottom;positionChrome();return in;}); ViewCompat.requestApplyInsets(root);
        showTab("map",false); ensureLocation(); if(prefs.getBoolean("keep_screen",true))getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        if(store.hasDraft())root.postDelayed(this::offerDraftRecovery,450);
    }

    private void buildMap(){
        map=new MapView(this);map.setTileSource(TileSourceFactory.MAPNIK);map.setUseDataConnection(true);map.setMultiTouchControls(true);map.setTilesScaledToDpi(true);map.setMinZoomLevel(3.0);map.setMaxZoomLevel(20.0);map.getController().setZoom(17.5);root.addView(map,new FrameLayout.LayoutParams(-1,-1));
        me=new MyLocationNewOverlay(new GpsMyLocationProvider(this),map);me.setDrawAccuracyEnabled(false);map.getOverlays().add(me);remainingLine=new Polyline();remainingLine.getOutlinePaint().setStrokeCap(Paint.Cap.ROUND);map.getOverlays().add(remainingLine);routeArrows=new RouteArrowsOverlay();map.getOverlays().add(routeArrows);
    }

    private View buildTopBar(){LinearLayout b=new LinearLayout(this);b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(dp(10),dp(7),dp(8),dp(7));b.setBackground(round(SURFACE,24));b.setElevation(dp(8));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.routix_logo);logo.setScaleType(ImageView.ScaleType.CENTER_CROP);b.addView(logo,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout brand=new LinearLayout(this);brand.setOrientation(LinearLayout.VERTICAL);brand.setPadding(dp(10),0,0,0);brand.addView(text("Routix",19,Typeface.BOLD,TEXT));brand.addView(text("terrain • tournées • guidage",10,Typeface.NORMAL,MUTED));b.addView(brand,new LinearLayout.LayoutParams(0,-2,1));headerSpeed=new CompactSpeedometer(this);b.addView(headerSpeed,new LinearLayout.LayoutParams(dp(76),dp(50)));TextView loc=icon("◎");loc.setOnClickListener(v->recenter());b.addView(loc,new LinearLayout.LayoutParams(dp(44),dp(44)));return b;}

    private View buildDock(){HorizontalScrollView s=new HorizontalScrollView(this);s.setHorizontalScrollBarEnabled(false);s.setFillViewport(true);s.setBackground(round(SURFACE,24));s.setElevation(dp(10));LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER);tab(r,"⌖","Carte","map");tab(r,"●","Enregistrer","record");tab(r,"≡","Tournées","routes");tab(r,"➜","GPS","gps");tab(r,"◷","Heures","hours");tab(r,"⚙","Réglages","settings");s.addView(r,new HorizontalScrollView.LayoutParams(-2,-1));return s;}
    private void tab(LinearLayout row,String glyph,String label,String key){TextView t=text(glyph+"\n"+label,10,Typeface.BOLD,MUTED);t.setGravity(Gravity.CENTER);t.setTag(key);t.setMinWidth(dp(78));t.setPadding(dp(8),dp(5),dp(8),dp(5));t.setOnClickListener(v->{press(v);if("gps".equals(key)){startActivity(new Intent(this,ClassicNavigationActivity.class));return;}showTab(key,true);});row.addView(t,new LinearLayout.LayoutParams(dp(88),-1));}

    private void showTab(String key,boolean animate){selectedTab=key; contentHost.removeAllViews(); boolean mapMode="map".equals(key);map.setVisibility(mapMode?View.VISIBLE:View.GONE);topBar.setVisibility(View.VISIBLE); if(mapMode)contentHost.addView(mapCard()); else if("record".equals(key))contentHost.addView(recordPage()); else if("routes".equals(key))contentHost.addView(routesPage()); else if("hours".equals(key))contentHost.addView(hoursPage()); else if("settings".equals(key))contentHost.addView(settingsPage());recordSheet="record".equals(key)?contentHost:null;updateDock();positionChrome();if(animate&&prefs.getBoolean("animations",true)){contentHost.setAlpha(0);contentHost.setTranslationY(dp(10));contentHost.animate().alpha(1).translationY(0).setDuration(180).start();}}
    private void updateDock(){ViewGroup r=(ViewGroup)((HorizontalScrollView)dock).getChildAt(0);for(int i=0;i<r.getChildCount();i++){TextView t=(TextView)r.getChildAt(i);boolean on=selectedTab.equals(t.getTag());t.setTextColor(on?accent:MUTED);t.setBackground(on?round(SURFACE2,18):null);}}

    private View mapCard(){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackground(round(Color.argb(238,30,30,46),24));guideTitle=text(guiding?"Suis les flèches":"Carte",17,Typeface.BOLD,TEXT);card.addView(guideTitle);TextView sub=text(guiding?"Le tracé parcouru disparaît automatiquement":"Enregistre ou sélectionne une tournée pour commencer",11,Typeface.NORMAL,MUTED);card.addView(sub);LinearLayout row=new LinearLayout(this);row.setPadding(0,dp(9),0,0);guideDistance=metric("—","RESTANT");guideProgress=metric("—","PROGRESSION");row.addView(guideDistance,new LinearLayout.LayoutParams(0,dp(58),1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(58),1);p.leftMargin=dp(8);row.addView(guideProgress,p);card.addView(row);if(guiding){TextView stop=pill("Arrêter le guidage",SURFACE2);stop.setOnClickListener(v->{guiding=false;guidance=null;guidingRoute=null;remainingLine.setPoints(new ArrayList<>());routeArrows.setPoints(new ArrayList<>());showTab("map",false);});card.addView(stop,new LinearLayout.LayoutParams(-1,dp(44)));}return card;}

    private View recordPage(){ScrollView sv=new ScrollView(this);LinearLayout p=page("Enregistrer","Un écran dédié au terrain, rien de plus.");recordStatus=text(recording?(paused?"EN PAUSE":"ENREGISTREMENT ACTIF"):"PRÊT",13,Typeface.BOLD,recording?GREEN:MUTED);p.addView(recordStatus);LinearLayout stats=new LinearLayout(this);stats.setPadding(0,dp(12),0,dp(12));recordDistance=metric(formatDistance(recordedDistance),"DISTANCE");recordPoints=metric(String.valueOf(recordingPoints.size()),"POINTS");recordEvents=metric(String.valueOf(recordingEvents.size()),"REPÈRES");stats.addView(recordDistance,new LinearLayout.LayoutParams(0,dp(66),1));stats.addView(recordPoints,new LinearLayout.LayoutParams(0,dp(66),1));stats.addView(recordEvents,new LinearLayout.LayoutParams(0,dp(66),1));p.addView(stats);recordMain=pill(recording?"Terminer et sauvegarder":"Commencer l’enregistrement",recording?RED:accent);recordMain.setOnClickListener(v->{press(v);if(recording)finishRecording();else startRecording();});p.addView(recordMain,new LinearLayout.LayoutParams(-1,dp(58)));LinearLayout flags=new LinearLayout(this);flags.setPadding(0,dp(10),0,0);reverseButton=pill("↶ Marche arrière",PEACH);twoSidesButton=pill("⇆ 2 côtés",GREEN);reverseButton.setOnClickListener(v->addEvent("REVERSE","Marche arrière"));twoSidesButton.setOnClickListener(v->addEvent("TWO_SIDES","2 côtés"));flags.addView(reverseButton,new LinearLayout.LayoutParams(0,dp(52),1));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(0,dp(52),1);fp.leftMargin=dp(8);flags.addView(twoSidesButton,fp);p.addView(flags);pauseButton=pill(paused?"Reprendre":"Pause",SURFACE2);pauseButton.setOnClickListener(v->togglePause());LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(46));pp.topMargin=dp(8);p.addView(pauseButton,pp);setFlagEnabled(recording&&!paused);TextView info=text("Les tournées finalisées sont aussi copiées dans Téléchargements/Routix : elles survivent à la désinstallation.",12,Typeface.NORMAL,MUTED);info.setPadding(0,dp(18),0,0);p.addView(info);sv.addView(p);return sv;}

    private View routesPage(){ScrollView sv=new ScrollView(this);LinearLayout p=page("Tournées","Import, guidage, plans et partage.");LinearLayout actions=new LinearLayout(this);TextView imp=pill("Importer GPX",accent);imp.setOnClickListener(v->importGpx());TextView rec=pill("Nouvelle tournée",SURFACE2);rec.setOnClickListener(v->showTab("record",true));actions.addView(imp,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,dp(48),1);rp.leftMargin=dp(8);actions.addView(rec,rp);p.addView(actions);List<File> files=store.routeFiles();if(files.isEmpty()){TextView e=text("Aucune tournée. Importe un GPX ou enregistre ton premier parcours.",13,Typeface.NORMAL,MUTED);e.setPadding(0,dp(24),0,0);p.addView(e);}for(File f:files)p.addView(routeCard(f));sv.addView(p);return sv;}
    private View routeCard(File f){RouteStore.Summary s=store.parse(f);LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(13),dp(14),dp(13));c.setBackground(round(SURFACE,20));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(10);c.setLayoutParams(cp);c.addView(text(store.displayName(f),16,Typeface.BOLD,TEXT));c.addView(text(formatDistance(s.distanceM)+" • "+s.points.size()+" points • "+s.events.size()+" repères",11,Typeface.NORMAL,MUTED));LinearLayout a=new LinearLayout(this);a.setPadding(0,dp(10),0,0);TextView guide=pill("Guider",accent);guide.setOnClickListener(v->startGuidance(s));TextView plan=pill("Plan",SURFACE2);plan.setOnClickListener(v->PrintablePlan.open(this,s,store.displayName(f)));TextView more=pill("•••",SURFACE2);more.setOnClickListener(v->routeMenu(f,s));a.addView(guide,new LinearLayout.LayoutParams(0,dp(44),1));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,dp(44),1);ap.leftMargin=dp(7);a.addView(plan,ap);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(dp(58),dp(44));mp.leftMargin=dp(7);a.addView(more,mp);c.addView(a);return c;}
    private void routeMenu(File f,RouteStore.Summary s){String[] x={"Renommer","Dupliquer","Partager le GPX","Générer le plan","Supprimer de l’application"};new AlertDialog.Builder(this).setTitle(store.displayName(f)).setItems(x,(d,w)->{if(w==0)rename(f);else if(w==1){store.duplicate(f);showTab("routes",false);}else if(w==2)share(f);else if(w==3)PrintablePlan.open(this,s,store.displayName(f));else new AlertDialog.Builder(this).setTitle("Supprimer ?").setMessage("La copie durable dans Téléchargements/Routix reste conservée.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(a,b)->{store.delete(f);showTab("routes",false);}).show();}).show();}
    private void rename(File f){EditText e=new EditText(this);e.setText(store.displayName(f));e.setSingleLine(true);new AlertDialog.Builder(this).setTitle("Nom de la tournée").setView(e).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{store.rename(f,e.getText().toString());showTab("routes",false);}).show();}
    private void share(File f){try{Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/gpx+xml");i.putExtra(Intent.EXTRA_STREAM,u);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Partager la tournée"));}catch(Exception e){toast("Partage impossible");}}

    private View hoursPage(){ScrollView sv=new ScrollView(this);LinearLayout p=page("Heures","Suivi mensuel, séparé du GPS.");String month=new SimpleDateFormat("yyyy-MM",Locale.FRANCE).format(new Date());int total=hoursStore.totalForMonth(month);TextView totalView=metric(formatMinutes(total),"CE MOIS");p.addView(totalView,new LinearLayout.LayoutParams(-1,dp(76)));TextView add=pill("Ajouter une journée",accent);add.setOnClickListener(v->addHours());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(50));ap.topMargin=dp(10);p.addView(add,ap);for(WorkHoursStore.Entry e:hoursStore.entries()){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setBackground(round(SURFACE,18));TextView info=text(e.date+"\n"+formatMinutes(e.netMinutes())+" • pause "+e.pauseMinutes+" min",12,Typeface.BOLD,TEXT);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView del=icon("×");del.setOnClickListener(v->{hoursStore.delete(e.id);showTab("hours",false);});row.addView(del,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);p.addView(row,lp);}sv.addView(p);return sv;}
    private void addHours(){final int[] v={7*60,14*60,30};TimePickerDialog start=new TimePickerDialog(this,(d,h,m)->{v[0]=h*60+m;TimePickerDialog end=new TimePickerDialog(this,(d2,h2,m2)->{v[1]=h2*60+m2;EditText pause=new EditText(this);pause.setHint("Pause en minutes");new AlertDialog.Builder(this).setTitle("Pause").setView(pause).setPositiveButton("Enregistrer",(x,w)->{try{v[2]=Integer.parseInt(pause.getText().toString());}catch(Exception ignored){}String date=new SimpleDateFormat("yyyy-MM-dd",Locale.FRANCE).format(new Date());hoursStore.add(date,v[0],v[1],v[2]);showTab("hours",false);}).show();},14,0,true);end.setTitle("Fin");end.show();},7,0,true);start.setTitle("Début");start.show();}

    private View settingsPage(){ScrollView sv=new ScrollView(this);LinearLayout p=page("Réglages","Sobre par défaut, personnalisable quand tu veux.");p.addView(section("Apparence"));LinearLayout colors=new LinearLayout(this);for(int c:new int[]{MAUVE,Color.rgb(137,180,250),GREEN,PEACH,Color.rgb(244,184,228)}){TextView b=icon("●");b.setTextColor(c);b.setOnClickListener(v->{accent=c;prefs.edit().putInt("accent_color",c).apply();showTab("settings",false);});colors.addView(b,new LinearLayout.LayoutParams(0,dp(50),1));}p.addView(colors);p.addView(toggle("Animations et micro-interactions","animations",true));p.addView(toggle("Garder l’écran allumé","keep_screen",true));p.addView(section("Guidage"));TextView threshold=pill("Tolérance hors tracé : "+prefs.getInt("offroute_m",45)+" m",SURFACE2);threshold.setOnClickListener(v->{int[] values={30,45,60,80};String[] labels={"30 m • précis","45 m • équilibré","60 m • urbain","80 m • GPS difficile"};new AlertDialog.Builder(this).setTitle("Tolérance hors tracé").setItems(labels,(d,w)->{prefs.edit().putInt("offroute_m",values[w]).apply();showTab("settings",false);}).show();});p.addView(threshold,new LinearLayout.LayoutParams(-1,dp(48)));TextView width=pill("Épaisseur du tracé : "+prefs.getInt("route_width",10),SURFACE2);width.setOnClickListener(v->{int n=prefs.getInt("route_width",10);n=n>=14?6:n+2;prefs.edit().putInt("route_width",n).apply();width.setText("Épaisseur du tracé : "+n);});LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(-1,dp(48));wp.topMargin=dp(8);p.addView(width,wp);p.addView(section("Stockage"));p.addView(text("Copie durable automatique : Téléchargements/Routix\nLes fichiers restent présents après désinstallation et sont réimportés au prochain lancement quand Android le permet.",12,Typeface.NORMAL,MUTED));sv.addView(p);return sv;}
    private View toggle(String label,String key,boolean def){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(10),dp(12),dp(10));row.setBackground(round(SURFACE,18));row.addView(text(label,13,Typeface.BOLD,TEXT),new LinearLayout.LayoutParams(0,-2,1));Switch s=new Switch(this);s.setChecked(prefs.getBoolean(key,def));s.setOnCheckedChangeListener((b,on)->{prefs.edit().putBoolean(key,on).apply();if("keep_screen".equals(key)){if(on)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}});row.addView(s);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);row.setLayoutParams(lp);return row;}

    private void startRecording(){recordingPoints.clear();recordingEvents.clear();recordedDistance=0;paused=false;pausedTotal=0;recordingStarted=System.currentTimeMillis();recording=true;if(lastLocation!=null)addRecordingFix(lastLocation,true);showTab("record",false);}
    private void finishRecording(){if(recordingPoints.size()<2){toast("Pas assez de points GPS");return;}recording=false;paused=false;setFlagEnabled(false);toast("Optimisation du tracé…");List<RouteStore.Point> p=new ArrayList<>(recordingPoints);List<RouteStore.Event> e=new ArrayList<>(recordingEvents);long started=recordingStarted;new Thread(()->{File f=store.createRoute(p,e,started);store.clearDraft();runOnUiThread(()->{recordingPoints.clear();recordingEvents.clear();recordedDistance=0;toast(f==null?"Sauvegarde impossible":"Tournée sauvegardée");showTab("routes",false);});},"routix-save").start();}
    private void togglePause(){if(!recording)return;if(!paused){paused=true;pauseStarted=System.currentTimeMillis();}else{paused=false;pausedTotal+=System.currentTimeMillis()-pauseStarted;if(lastLocation!=null)addRecordingFix(lastLocation,true);}showTab("record",false);}
    private void addEvent(String type,String label){if(!recording||paused||lastLocation==null){toast("Enregistrement GPS requis");return;}recordingEvents.add(new RouteStore.Event(type,label,lastLocation.getLatitude(),lastLocation.getLongitude(),System.currentTimeMillis(),lastLocation.hasAccuracy()?lastLocation.getAccuracy():0));press("REVERSE".equals(type)?reverseButton:twoSidesButton);refreshRecord();}
    private void addRecordingFix(Location l,boolean force){if(!recording||paused||l==null)return;if(l.hasAccuracy()&&l.getAccuracy()>45)return;RouteStore.Point p=new RouteStore.Point(l.getLatitude(),l.getLongitude(),l.getTime()>0?l.getTime():System.currentTimeMillis(),l.hasAccuracy()?l.getAccuracy():0);if(!recordingPoints.isEmpty()){RouteStore.Point prev=recordingPoints.get(recordingPoints.size()-1);double d=RouteNormalizer.distanceM(prev,p);if(!force&&d<2)return;if(d<250)recordedDistance+=d;}recordingPoints.add(p);if(System.currentTimeMillis()-lastDraftAt>15000){lastDraftAt=System.currentTimeMillis();store.saveDraft(recordingPoints,recordingEvents,recordingStarted);}refreshRecord();}
    private void refreshRecord(){if(recordDistance!=null)recordDistance.setText(formatDistance(recordedDistance)+"\nDISTANCE");if(recordPoints!=null)recordPoints.setText(recordingPoints.size()+"\nPOINTS");if(recordEvents!=null)recordEvents.setText(recordingEvents.size()+"\nREPÈRES");}
    private void setFlagEnabled(boolean on){for(TextView t:new TextView[]{reverseButton,twoSidesButton,pauseButton})if(t!=null){t.setEnabled(on);t.setAlpha(on?1:.4f);}}
    private void offerDraftRecovery(){RouteStore.Summary d=store.draftSummary();new AlertDialog.Builder(this).setTitle("Tournée interrompue").setMessage(d.points.size()+" points peuvent être récupérés.").setNegativeButton("Ignorer",(x,w)->store.clearDraft()).setPositiveButton("Récupérer",(x,w)->{recordingPoints.clear();recordingPoints.addAll(d.points);recordingEvents.clear();recordingEvents.addAll(d.events);recordedDistance=d.distanceM;recordingStarted=d.firstTime>0?d.firstTime:System.currentTimeMillis();recording=true;paused=false;showTab("record",true);}).show();}

    private void importGpx(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_GPX);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==IMPORT_GPX&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();toast("Analyse et recalage du GPX…");new Thread(()->{File f=store.importGpx(u);runOnUiThread(()->{toast(f==null?"Import impossible":"GPX importé et optimisé");showTab("routes",false);});},"routix-import").start();}}

    private void startGuidance(RouteStore.Summary s){if(s==null||s.points.size()<2)return;List<GuidanceEngine.Point> p=new ArrayList<>();for(RouteStore.Point q:s.points)p.add(new GuidanceEngine.Point(q.lat,q.lon));List<GuidanceEngine.Event> e=new ArrayList<>();for(RouteStore.Event q:s.events)e.add(new GuidanceEngine.Event(q.type,q.label,q.lat,q.lon));guidance=new GuidanceEngine(p,e);guidance.setOffRouteThreshold(prefs.getInt("offroute_m",45));guidingRoute=s;guiding=true;if(lastLocation!=null)guidance.reposition(lastLocation.getLatitude(),lastLocation.getLongitude());showTab("map",true);drawRemaining(null);fitRoute(s);}
    private void drawRemaining(GuidanceEngine.State state){if(!guiding||guidingRoute==null)return;int start=state==null?0:Math.max(0,Math.min(guidingRoute.points.size()-2,state.nearestIndex));List<GeoPoint> pts=new ArrayList<>();if(state!=null&&Double.isFinite(state.position.lat))pts.add(new GeoPoint(state.position.lat,state.position.lon));for(int i=start+1;i<guidingRoute.points.size();i++){RouteStore.Point p=guidingRoute.points.get(i);pts.add(new GeoPoint(p.lat,p.lon));}remainingLine.setPoints(pts);remainingLine.getOutlinePaint().setColor(accent);remainingLine.getOutlinePaint().setStrokeWidth(dp(prefs.getInt("route_width",10)));routeArrows.setPoints(pts);map.invalidate();}
    private void fitRoute(RouteStore.Summary s){double n=-90,so=90,e=-180,w=180;for(RouteStore.Point p:s.points){n=Math.max(n,p.lat);so=Math.min(so,p.lat);e=Math.max(e,p.lon);w=Math.min(w,p.lon);}BoundingBox box=new BoundingBox(n,e,so,w);map.post(()->map.zoomToBoundingBox(box,true,dp(70)));}

    @Override public void onLocationChanged(@NonNull Location l){lastLocation=l;headerSpeed.update(l);addRecordingFix(l,false);if(guiding&&guidance!=null){GuidanceEngine.State s=guidance.update(l.getLatitude(),l.getLongitude(),l.getTime()>0?l.getTime():System.currentTimeMillis(),l.hasAccuracy()?l.getAccuracy():8);drawRemaining(s);if(guideDistance!=null)guideDistance.setText(formatDistance(s.remainingM)+"\nRESTANT");if(guideProgress!=null)guideProgress.setText(s.progressPercent+" %\nPROGRESSION");if(guideTitle!=null)guideTitle.setText(s.finished?"Tournée terminée":s.offRoute?"Rejoins le tracé":"Suis les flèches");}}
    private void ensureLocation(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOCATION_PERMISSION);return;}try{me.enableMyLocation();lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,1.5f,this);if(lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER))lm.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,2500,5,this);}catch(Exception ignored){}}
    @Override public void onRequestPermissionsResult(int r,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOCATION_PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)ensureLocation();}
    private void recenter(){if(lastLocation==null){toast("GPS en attente");return;}map.getController().animateTo(new GeoPoint(lastLocation.getLatitude(),lastLocation.getLongitude()));map.getController().setZoom(18.2);}

    private LinearLayout page(String title,String sub){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(16),dp(18),dp(16),dp(24));p.addView(text(title,28,Typeface.BOLD,TEXT));TextView s=text(sub,12,Typeface.NORMAL,MUTED);s.setPadding(0,dp(3),0,dp(14));p.addView(s);return p;}
    private TextView section(String s){TextView t=text(s.toUpperCase(Locale.ROOT),10,Typeface.BOLD,accent);t.setPadding(0,dp(18),0,dp(7));return t;}
    private TextView text(String s,float size,int style,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create("sans-serif",style));t.setIncludeFontPadding(false);return t;}
    private TextView pill(String s,int color){TextView t=text(s,13,Typeface.BOLD,(color==accent||color==GREEN||color==PEACH||color==RED)?BG:TEXT);t.setGravity(Gravity.CENTER);t.setBackground(round(color,18));return t;}
    private TextView metric(String value,String label){TextView t=text(value+"\n"+label,13,Typeface.BOLD,TEXT);t.setGravity(Gravity.CENTER);t.setBackground(round(SURFACE,18));return t;}
    private TextView icon(String s){TextView t=text(s,20,Typeface.BOLD,TEXT);t.setGravity(Gravity.CENTER);t.setBackground(round(SURFACE2,16));return t;}
    private GradientDrawable round(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));g.setStroke(dp(1),Color.argb(34,255,255,255));return g;}
    private void press(View v){if(v==null)return;v.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);if(prefs.getBoolean("animations",true))v.animate().scaleX(.96f).scaleY(.96f).setDuration(65).withEndAction(()->v.animate().scaleX(1).scaleY(1).setDuration(120).start()).start();}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private static String formatDistance(double m){return m<1000?Math.round(m)+" m":String.format(Locale.FRANCE,"%.1f km",m/1000d);}
    private static String formatMinutes(int m){return String.format(Locale.FRANCE,"%dh%02d",m/60,m%60);}

    private void positionChrome(){if(root==null||topBar==null||dock==null||contentHost==null)return;int top=systemTop+dp(8),bottom=systemBottom+dp(8);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,dp(64),Gravity.TOP);hp.setMargins(dp(10),top,dp(10),0);topBar.setLayoutParams(hp);FrameLayout.LayoutParams dpv=new FrameLayout.LayoutParams(-1,dp(68),Gravity.BOTTOM);dpv.setMargins(dp(10),0,dp(10),bottom);dock.setLayoutParams(dpv);if("map".equals(selectedTab)){FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);cp.setMargins(dp(10),0,dp(10),bottom+dp(76));contentHost.setLayoutParams(cp);}else{FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-1);cp.setMargins(0,top+dp(72),0,bottom+dp(76));contentHost.setLayoutParams(cp);}}

    @Override protected void onResume(){super.onResume();if(map!=null)map.onResume();}
    @Override protected void onPause(){super.onPause();if(map!=null)map.onPause();if(recording)store.saveDraft(recordingPoints,recordingEvents,recordingStarted);}
    @Override protected void onDestroy(){try{lm.removeUpdates(this);}catch(Exception ignored){}if(me!=null)me.disableMyLocation();if(map!=null)map.onDetach();super.onDestroy();}
    @Override public void onProviderEnabled(@NonNull String provider){} @Override public void onProviderDisabled(@NonNull String provider){}
}
